rtl/reference/top_module.v.content:
module top_module(input wire clk, input wire rst, input wire en,
                  output reg [3:0] count);
always @(posedge clk) begin
    if (rst) count <= 4'd0;
    else if (en) count <= count + 4'd1;
end
endmodule

rtl/test/tb.v.content:
`timescale 1ns/1ps
module tb;
reg clk = 0;
reg rst = 0;
reg en = 0;
wire [3:0] count;
reg [3:0] expected = 0;
integer checks = 0;
integer i;
top_module dut(.clk(clk), .rst(rst), .en(en), .count(count));
always #5 clk = ~clk;
task tick;
    input next_rst;
    input next_en;
    begin
        @(negedge clk);
        rst = next_rst;
        en = next_en;
        @(posedge clk);
        if (next_rst) expected = 4'd0;
        else if (next_en) expected = expected + 4'd1;
        #1;
        checks = checks + 1;
        if (count !== expected) begin
            $display("QB_CHECK_FAIL index=%0d time=%0t expected=%0d actual=%0d",
                     checks, $time, expected, count);
            $fatal(1, "counter mismatch");
        end
    end
endtask
initial begin
    $timeformat(-9, 1, " ns", 0);
    $dumpfile("wave.vcd");
    $dumpvars(0, tb);
    tick(1, 0);
    for (i = 0; i < 18; i = i + 1) tick(0, 1);
    tick(0, 0);
    tick(1, 1);
    tick(0, 0);
    tick(0, 1);
    tick(0, 1);
    if (checks != 24) $fatal(1, "incomplete checks");
    $display("QB_TEST_DONE checks=%0d", checks);
    $finish;
end
initial begin
    #400;
    $fatal(1, "simulation timeout");
end
endmodule

